def _guess_type(ty: type[t.Any] | ParamType[t.Any] | None, default: t.Any | None) -> type[t.Any] | tuple[type[t.Any], ...] | ParamType[t.Any] | None:
    if ty is not None:
        return ty
    if default is None:
        return None
    if not isinstance(default, (tuple, list)):
        return type(default)
    if not default:
        return None
    item = default[0]
    if isinstance(item, (tuple, list)):
        return tuple(map(type, item))
    return type(item)
