def fake_traceback(exc_value: BaseException, tb: TracebackType | None, filename: str, lineno: int) -> TracebackType:
    if tb is not None:
        locals = get_template_locals(tb.tb_frame.f_locals)
        locals.pop('__jinja_exception__', None)
    else:
        locals = {}
    globals = {'__name__': filename, '__file__': filename, '__jinja_exception__': exc_value}
    code: CodeType = compile('\n' * (lineno - 1) + 'raise __jinja_exception__', filename, 'exec')
    location = 'template'
    if tb is not None:
        function = tb.tb_frame.f_code.co_name
        if function == 'root':
            location = 'top-level template code'
        elif function.startswith('block_'):
            location = f'block {function[6:]!r}'
    code = code.replace(co_name=location)
    try:
        exec(code, globals, locals)
    except BaseException:
        return sys.exc_info()[2].tb_next
