def new_context(environment: 'Environment', template_name: str | None, blocks: dict[str, t.Callable[['Context'], t.Iterator[str]]], vars: dict[str, t.Any] | None=None, shared: bool=False, globals: t.MutableMapping[str, t.Any] | None=None, locals: t.Mapping[str, t.Any] | None=None) -> 'Context':
    if vars is None:
        vars = {}
    if shared:
        parent = vars
    else:
        parent = dict(globals or (), **vars)
    if locals:
        if shared:
            parent = dict(parent)
